use verus::prelude::*;

#[verifier::trusted]
#[verifier::requires(lst.len() > 0)]
#[verifier::ensures(
    // The result is at least as large as every element in the original list
    forall(|i: usize| i < lst.len() ==> result >= lst[i])
)]
#[verifier::ensures(
    // The result actually appears as one of the elements of the original list
    exists(|i: usize| i < lst.len() && result == lst[i])
)]
fn max_of_list(lst: Vec<i32>) -> i32 {
    // Since the list is guaranteed to be non-empty, we can safely call `max()`
    // and then `unwrap()` the `Option<i32>` it returns.
    lst.into_iter().max().unwrap()
}

fn main() {
    let numbers = vec![3, -1, 7, 0, 5];
    println!("The maximum is {}", max_of_list(numbers)); // Should print 7.
}